I'll build a fully self-contained 3D snow globe using a custom software 3D renderer on canvas (no external libraries, since network/CDN deps aren't allowed). Let me start with the core file.

{"action":"write_file","path":"index.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<title>Alpine Snow Globe</title>
<style>
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;background:#060a13;overflow:hidden;
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    color:#dbe6ff;-webkit-tap-highlight-color:transparent;
  }
  canvas{position:fixed;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:grab}
  canvas.grabbing{cursor:grabbing}
  #ui{position:fixed;top:3.2vh;left:0;right:0;text-align:center;pointer-events:none;padding:0 18px;z-index:3}
  #ui h1{
    margin:0;font-size:clamp(15px,2.3vw,26px);font-weight:600;letter-spacing:.24em;
    text-transform:uppercase;color:#eaf1ff;text-shadow:0 0 26px rgba(110,160,255,.55)
  }
  #ui p{margin:9px 0 0;font-size:clamp(10px,1.15vw,13px);letter-spacing:.09em;color:#8296b8}
  #ui p b{color:#b9cdec;font-weight:600}
  #shakeBtn{
    position:fixed;left:50%;bottom:3.4vh;transform:translateX(-50%);z-index:3;
    padding:11px 32px;border-radius:999px;border:1px solid rgba(150,190,255,.35);
    background:linear-gradient(180deg,rgba(120,165,255,.20),rgba(60,100,190,.14));
    color:#dce9ff;font-size:12px;font-weight:600;letter-spacing:.20em;text-transform:uppercase;
    cursor:pointer;font-family:inherit;
    transition:transform .18s,box-shadow .25s,background .25s;
  }
  #shakeBtn:hover{background:linear-gradient(180deg,rgba(140,185,255,.32),rgba(70,115,205,.22));box-shadow:0 0 28px rgba(110,160,255,.45)}
  #shakeBtn:active{transform:translateX(-50%) scale(.95)}
  @media (max-height:520px){#ui p{display:none}}
</style>
</head>
<body>
<canvas id="scene"></canvas>
<div id="ui">
  <h1>Alpine Snow Globe</h1>
  <p><b>Drag</b> to orbit &nbsp;&middot;&nbsp; <b>Scroll</b> or pinch to zoom &nbsp;&middot;&nbsp; <b>Click</b> the glass to shake</p>
</div>
<button id="shakeBtn" type="button">Shake</button>
<script>
(function(){
'use strict';

var canvas = document.getElementById('scene');
var ctx = canvas.getContext('2d', {alpha:false});

/* ---------------- helpers ---------------- */
function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function lerp(a,b,t){ return a+(b-a)*t; }
function smoothstep(e0,e1,x){ var t=(x-e0)/(e1-e0); t=t<0?0:(t>1?1:t); return t*t*(3-2*t); }

/* ---------------- viewport ---------------- */
var VW=1, VH=1, DPR=1;
var cx=0, cy=0, R=0, P=1, baseR=0, zoom=1;
var DIST=4.4, SR=1.5;

var yaw=0.75, pitch=0.26, vYaw=0, vPitch=0;
var shakeAmp=0;
var lastInteract=0;

/* ---------------- lighting ---------------- */
var LX=-0.42, LY=0.80, LZ=0.43;
(function(){ var l=Math.sqrt(LX*LX+LY*LY+LZ*LZ); LX/=l; LY/=l; LZ/=l; })();

function shade(r,g,b,nx,ny,nz){
  var ndl = nx*LX + ny*LY + nz*LZ;
  if(ndl<0) ndl=0;
  var s = 0.40 + 0.82*ndl;
  var amb = 1-ndl;
  var rr = r*s + amb*0.015;
  var gg = g*s + amb*0.032;
  var bb = b*s + amb*0.075;
  return 'rgb(' + ((clamp(rr,0,1)*255)|0) + ',' + ((clamp(gg,0,1)*255)|0) + ',' + ((clamp(bb,0,1)*255)|0) + ')';
}

/* ---------------- terrain height field ---------------- */
var BASE_Y = -1.02, H_SCALE = 0.92;

function heightAt(x,z){
  var r2 = x*x + z*z;
  var r = Math.sqrt(r2);
  var h = Math.exp(-r2/0.30);
  h += 0.42*Math.exp(-((x+0.42)*(x+0.42)/0.10 + (z-0.30)*(z-0.30)/0.11));
  h += 0.30*Math.exp(-((x-0.30)*(x-0.30)/0.09 + (z+0.35)*(z+0.35)/0.12));
  h += 0.09*Math.sin(x*5.3+1.2)*Math.cos(z*4.9-0.7)*Math.exp(-r2*0.9);
  h += 0.05*Math.sin(x*9.1-2.0)*Math.cos(z*8.3+1.0)*Math.exp(-r2*1.4);
  h *= (1 - smoothstep(0.60, 1.02, r));
  if(h<0) h=0;
  if(h>1.15) h=1.15;
  return h;
}

var C_ROCK=[0.40,0.375,0.385], C_MOSS=[0.20,0.30,0.23], C_SNOW=[0.95,0.97,1.0];
function terrainColor(h,nx,ny,nz,vv){
  var altSnow = smoothstep(0.38,0.82,h);
  var r=C_ROCK[0], g=C_ROCK[1], b=C_ROCK[2];
  var moss = smoothstep(0.32,0.72,ny)*(1-altSnow*0.85);
  r=lerp(r,C_MOSS[0],moss); g=lerp(g,C_MOSS[1],moss); b=lerp(b,C_MOSS[2],moss);
  var sf = clamp(smoothstep(0.40,0.88,ny) + altSnow*0.85, 0, 1);
  r=lerp(r,C_SNOW[0],sf); g=lerp(g,C_SNOW[1],sf); b=lerp(b,C_SNOW[2],sf);
  var j = ((vv*37)%7)/7*0.06 - 0.03;
  r=clamp(r+j,0,1); g=clamp(g+j,0,1); b=clamp(b+j,0,1);
  return shade(r,g,b,nx,ny,nz);
}

/* ---------------- build terrain mesh ---------------- */
var N = 30;
var G0 = -1.06, GD = (1.06 - (-1.06))/N;
var VN = (N+1)*(N+1);
var vX = new Float64Array(VN), vY = new Float64Array(VN), vZ = new Float64Array(VN), vH = new Float64Array(VN);
var sX = new Float64Array(VN), sY = new Float64Array(VN), sZ = new Float64Array(VN);

(function buildTerrain(){
  for(var j=0;j<=N;j++){
    for(var i=0;i<=N;i++){
      var x = G0 + i*GD, z = G0 + j*GD;
      var idx = j*(N+1)+i;
      var h = heightAt(x,z);
      vX[idx]=x; vZ[idx]=z; vH[idx]=h; vY[idx]=BASE_Y + h*H_SCALE;
    }
  }
})();

var quads = [];
(function buildQuads(){
  for(var j=0;j<N;j++){
    for(var i=0;i<N;i++){
      var a = j*(N+1)+i, b=a+1, c=a+N+2, d=a+N+1;
      var ra=Math.sqrt(vX[a]*vX[a]+vZ[a]*vZ[a]);
      var rb=Math.sqrt(vX[b]*vX[b]+vZ[b]*vZ[b]);
      var rc=Math.sqrt(vX[c]*vX[c]+vZ[c]*vZ[c]);
      var rd=Math.sqrt(vX[d]*vX[d]+vZ[d]*vZ[d]);
      if(ra>1.03 || rb>1.03 || rc>1.03 || rd>1.03) continue;
      var ux=vX[b]-vX[a], uy=vY[b]-vY[a], uz=vZ[b]-vZ[a];
      var wx=vX[d]-vX[a], wy=vY[d]-vY[a], wz=vZ[d]-vZ[a];
      var nx=uy*wz-uz*wy, ny=uz*wx-ux*wz, nz=ux*wy-uy*wx;
      var nl=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=nl; ny/=nl; nz/=nl;
      if(ny<0){ nx=-nx; ny=-ny; nz=-nz; }
      var mx=(vX[a]+vX[b]+vX[c]+vX[d])*0.25, my=(vY[a]+vY[b]+vY[c]+vY[d])*0.25, mz=(vZ[a]+vZ[b]+vZ[c]+vZ[d])*0.25;
      var hAvg=(vH[a]+vH[b]+vH[c]+vH[d])*0.25;
      quads.push({
        a:a,b:b,c:c,d:d, nx:nx,ny:ny,nz:nz, mx:mx,my:my,mz:mz,
        col:terrainColor(hAvg,nx,ny,nz,(i*7+j*13)%9)
      });
    }
  }
})();

/* ---------------- build trees ---------------- */
function mulberry32(a){
  return function(){
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a>>>15, 1|a);
    t = t + Math.imul(t ^ t>>>7, 61|t) ^ t;
    return ((t ^ t>>>14)>>>0)/4294967296;
  };
}

var treeFaces = [];
(function buildTrees(){
  var rnd = mulberry32(20260912);
  var spots = [];
  for(var k=0;k<400 && spots.length<14;k++){
    var ang = rnd()*Math.PI*2;
    var rad = 0.34 + rnd()*0.62;
    var x = Math.cos(ang)*rad, z = Math.sin(ang)*rad;
    var h = heightAt(x,z);
    if(h<0.05 || h>0.33) continue;
    spots.push({x:x,z:z,h:h});
  }
  for(var s=0;s<spots.length;s++){
    var sp = spots[s];
    var by = BASE_Y + sp.h*H_SCALE;
    addCone(sp.x, sp.z, by,        0.052, 0.075, 6, [0.10,0.22,0.15]);
    addCone(sp.x, sp.z, by+0.050,  0.042, 0.072, 6, [0.12,0.26,0.17]);
    addCone(sp.x, sp.z, by+0.100,  0.031, 0.066, 6, [0.42,0.54,0.50]);
  }
})();

function addCone(tx,tz,by,rad,hh,segs,col){
  var ax = tx, ay = by + hh*0.45, az = tz;
  for(var s=0;s<segs;s++){
    var a0 = s/segs*Math.PI*2, a1=(s+1)/segs*Math.PI*2;
    var x0 = tx + Math.cos(a0)*rad, z0 = tz + Math.sin(a0)*rad;
    var x1 = tx + Math.cos(a1)*rad, z1 = tz + Math.sin(a1)*rad;
    addTri(x0,by,z0, x1,by,z1, tx,by+hh,tz, col, ax,ay,az);
  }
}

function addTri(ax,ay,az, bx,by,bz, cxx,cyy,czz, col, refX,refY,refZ){
  var ux=bx-ax, uy=by-ay, uz=bz-az;
  var wx=cxx-ax, wy=cyy-ay, wz=czz-az;
  var nx=uy*wz-uz*wy, ny=uz*wx-ux*wz, nz=ux*wy-uy*wx;
  var nl=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=nl; ny/=nl; nz/=nl;
  var mx=(ax+bx+cxx)/3, my=(ay+by+cyy)/3, mz=(az+bz+czz)/3;
  if(refX!==undefined){
    var ox=mx-refX, oy=my-refY, oz=mz-refZ;
    if(nx*ox+ny*oy+nz*oz<0){ nx=-nx; ny=-ny; nz=-nz; }
  }
  treeFaces.push({
    ax:ax,ay:ay,az:az, bx:bx,by:by,bz:bz, cx:cxx,cy:cyy,cz:czz,
    nx:nx,ny:ny,nz:nz, mx:mx,my:my,mz:mz,
    col: shade(col[0],col[1],col[2],nx,ny,nz)
  });
}

/* ---------------- snow particles ---------------- */
var NP = 280;
var pxr = new Float64Array(NP), pyr = new Float64Array(NP), pzr = new Float64Array(NP);
var pvx = new Float64Array(NP), pvy = new Float64Array(NP), pvz = new Float64Array(NP);
var pph = new Float64Array(NP), prt = new Float64Array(NP);

function respawn(i,anywhere){
  var a = Math.random()*Math.PI*2;
  var rr = Math.sqrt(Math.random())*0.95;
  pxr[i] = Math.cos(a)*rr;
  pzr[i] = Math.sin(a)*rr;
  pyr[i] = anywhere ? (-0.9 + Math.random()*2.2) : (0.55 + Math.random()*0.85);
  pvx[i] = (Math.random()-0.5)*0.10;
  pvy[i] = -(0.02 + Math.random()*0.10);
  pvz[i] = (Math.random()-0.5)*0.10;
  pph[i] = Math.random()*Math.PI*2;
  prt[i] = 0;
}
for(var pi=0; pi<NP; pi++) respawn(pi, true);

function shake(strength){
  for(var i=0;i<NP;i++){
    prt[i]=0;
    pvx[i] += (Math.random()-0.5)*3.6*strength;
    pvy[i] += (1.0 + Math.random()*2.8)*strength;
    pvz[i] += (Math.random()-0.5)*3.6*strength;
    var sp = Math.sqrt(pvx[i]*pvx[i]+pvy[i]*pvy[i]+pvz[i]*pvz[i]);
    if(sp>6){ var k=6/sp; pvx[i]*=k; pvy[i]*=k; pvz[i]*=k; }
  }
  shakeAmp = 0.05*strength;
  lastInteract = performance.now();
}

function updateSnow(dt,t){
  for(var i=0;i<NP;i++){
    if(prt[i]>0){
      prt[i]-=dt;
      if(prt[i]<=0) respawn(i,false);
      continue;
    }
    pvy[i] -= 0.32*dt;
    pvx[i] += Math.sin(t*0.85 + pph[i])*0.24*dt;
    pvz[i] += Math.cos(t*1.05 + pph[i]*1.7)*0.24*dt;
    var dg = Math.exp(-0.55*dt);
    pvx[i]*=dg; pvy[i]*=dg; pvz[i]*=dg;
    pxr[i]+=pvx[i]*dt; pyr[i]+=pvy[i]*dt; pzr[i]+=pvz[i]*dt;

    var rr = Math.sqrt(pxr[i]*pxr[i] + pyr[i]*pyr[i] + pzr[i]*pzr[i]);
    if(rr>1.40){
      var s = 1.40/rr;
      pxr[i]*=s; pyr[i]*=s; pzr[i]*=s;
      var nx=pxr[i]/1.40, ny=pyr[i]/1.40, nz=pzr[i]/1.40;
      var vn = pvx[i]*nx + pvy[i]*ny + pvz[i]*nz;
      if(vn>0){ pvx[i]-=1.7*vn*nx; pvy[i]-=1.7*vn*ny; pvz[i]-=1.7*vn*nz; }
    }

    var r2 = pxr[i]*pxr[i] + pzr[i]*pzr[i];
    if(r2 < 1.02){
      var gy = BASE_Y + heightAt(pxr[i],pzr[i])*H_SCALE + 0.012;
      if(pyr[i] < gy){
        pyr[i] = gy;
        pvx[i]*=0.12; pvy[i]=0; pvz[i]*=0.12;
        prt[i] = 0.8 + Math.random()*2.8;
      }
    } else if(pyr[i] < -1.44){
      respawn(i,false);
    }
  }
}

/* soft snowflake sprite */
var sprite = document.createElement('canvas');
sprite.width = sprite.height = 32;
(function(){
  var sc = sprite.getContext('2d');
  var g = sc.createRadialGradient(16,16,0,16,16,16);
  g.addColorStop(0,'rgba(255,255,255,1)');
  g.addColorStop(0.35,'rgba(255,255,255,0.9)');
  g.addColorStop(0.7,'rgba(230,242,255,0.42)');
  g.addColorStop(1,'rgba(255,255,255,0)');
  sc.fillStyle=g; sc.fillRect(0,0,32,32);
})();

/* ---------------- resize ---------------- */
function resize(){
  DPR = Math.min(2, window.devicePixelRatio || 1);
  VW = window.innerWidth; VH = window.innerHeight;
  canvas.width = Math.max(1, Math.floor(VW*DPR));
  canvas.height = Math.max(1, Math.floor(VH*DPR));
  canvas.style.width = VW + 'px';
  canvas.style.height = VH + 'px';
  baseR = Math.min(VW*0.44, VH*0.28);
  cx = VW*0.5;
  cy = VH*0.46;
}
window.addEventListener('resize', resize);
resize();

function computeProjection(){
  R = baseR * zoom;
  P = R * Math.sqrt(DIST*DIST - SR*SR) / SR;
}

/* ---------------- draw: background & stand ---------------- */
function drawBackground(){
  var g = ctx.createLinearGradient(0,0,0,VH);
  g.addColorStop(0,'#0a1020');
  g.addColorStop(0.55,'#0c1424');
  g.addColorStop(1,'#05080f');
  ctx.fillStyle=g; ctx.fillRect(0,0,VW,VH);
  var rg = ctx.createRadialGradient(cx,cy,R*0.15, cx,cy, Math.max(R*2.6, 10));
  rg.addColorStop(0,'rgba(72,124,206,0.22)');
  rg.addColorStop(0.45,'rgba(48,88,158,0.09)');
  rg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=rg; ctx.fillRect(0,0,VW,VH);
}

var topY=0, topW=0, botY=0, botW=0;
function computeStand(){
  topY = cy + R*0.70; topW = R*0.80;
  botY = cy + R*1.30; botW = R*1.05;
}

function brassGradient(x0,x1){
  var gg = ctx.createLinearGradient(x0,0,x1,0);
  gg.addColorStop(0.00,'#5f451c');
  gg.addColorStop(0.18,'#e2c072');
  gg.addColorStop(0.42,'#a8842f');
  gg.addColorStop(0.62,'#e8cc81');
  gg.addColorStop(0.85,'#8a6a26');
  gg.addColorStop(1.00,'#4c3616');
  return gg;
}

function drawStand(){
  computeStand();
  /* ground shadow */
  var sg = ctx.createRadialGradient(cx, botY + botW*0.06, 0, cx, botY + botW*0.06, Math.max(botW*1.7,10));
  sg.addColorStop(0,'rgba(0,0,0,0.55)');
  sg.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=sg;
  ctx.beginPath(); ctx.ellipse(cx, botY + botW*0.05, botW*1.7, botW*0.42, 0, 0, Math.PI*2); ctx.fill();

  /* wooden body */
  var wg = ctx.createLinearGradient(cx-botW,0,cx+botW,0);
  wg.addColorStop(0.00,'#1d1109');
  wg.addColorStop(0.18,'#4a2c17');
  wg.addColorStop(0.45,'#7c4c27');
  wg.addColorStop(0.62,'#5a3419');
  wg.addColorStop(0.85,'#331d0f');
  wg.addColorStop(1.00,'#170d06');
  ctx.beginPath();
  ctx.moveTo(cx-topW, topY);
  ctx.bezierCurveTo(cx-topW*1.16, topY+R*0.30, cx-botW, botY-R*0.28, cx-botW, botY);
  ctx.lineTo(cx+botW, botY);
  ctx.bezierCurveTo(cx+botW, botY-R*0.28, cx+topW*1.16, topY+R*0.30, cx+topW, topY);
  ctx.closePath();
  ctx.fillStyle=wg; ctx.fill();

  /* bottom ellipse */
  var bg = ctx.createLinearGradient(cx-botW,0,cx+botW,0);
  bg.addColorStop(0,'#150c06'); bg.addColorStop(0.5,'#452a12'); bg.addColorStop(1,'#120a05');
  ctx.beginPath(); ctx.ellipse(cx, botY, botW, botW*0.24, 0, 0, Math.PI*2); ctx.fillStyle=bg; ctx.fill();

  /* top socket */
  var tg = ctx.createRadialGradient(cx-topW*0.3, topY-topW*0.08, 0, cx, topY, Math.max(topW*1.3,10));
  tg.addColorStop(0,'#8a5528'); tg.addColorStop(1,'#3a2110');
  ctx.beginPath(); ctx.ellipse(cx, topY, topW*1.06, topW*0.27, 0, 0, Math.PI*2); ctx.fillStyle=tg; ctx.fill();

  /* brass ring, back half */
  ctx.save();
  ctx.lineWidth = R*0.085;
  ctx.strokeStyle = brassGradient(cx-topW, cx+topW);
  ctx.beginPath(); ctx.ellipse(cx, topY, topW*1.06, topW*0.27, 0, Math.PI, Math.PI*2); ctx.stroke();
  ctx.restore();
}

function drawCollarFront(){
  ctx.save();
  ctx.lineWidth = R*0.085;
  ctx.strokeStyle = brassGradient(cx-topW, cx+topW);
  ctx.beginPath(); ctx.ellipse(cx, topY, topW*1.06, topW*0.27, 0, 0, Math.PI); ctx.stroke();
  ctx.restore();
}

/* ---------------- draw: glass ---------------- */
function drawGlass(){
  var d2 = R*2;
  ctx.save();
  ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.clip();

  var g = ctx.createRadialGradient(cx,cy,R*0.15, cx,cy,R);
  g.addColorStop(0,'rgba(150,190,255,0.02)');
  g.addColorStop(0.68,'rgba(150,190,255,0.05)');
  g.addColorStop(1,'rgba(198,224,255,0.32)');
  ctx.fillStyle=g; ctx.fillRect(cx-R,cy-R,d2,d2);

  var sg = ctx.createRadialGradient(cx, cy+R*0.78, R*0.05, cx, cy+R*0.78, Math.max(R*0.95,10));
  sg.addColorStop(0,'rgba(16,34,72,0.34)');
  sg.addColorStop(1,'rgba(16,34,72,0)');
  ctx.fillStyle=sg; ctx.fillRect(cx-R,cy-R,d2,d2);

  var hx = cx - R*0.40, hy = cy - R*0.46;
  var hg = ctx.createRadialGradient(hx,hy,0,hx,hy,Math.max(R*0.62,10));
  hg.addColorStop(0,'rgba(255,255,255,0.50)');
  hg.addColorStop(0.35,'rgba(255,255,255,0.14)');
  hg.addColorStop(1,'rgba(255,255,255,0)');
  ctx.fillStyle=hg;
  ctx.beginPath(); ctx.arc(hx,hy,R*0.62,0,Math.PI*2); ctx.fill();

  ctx.save();
  ctx.translate(cx - R*0.44, cy - R*0.50);
  ctx.rotate(-0.6);
  ctx.beginPath(); ctx.ellipse(0,0,R*0.20,R*0.062,0,0,Math.PI*2);
  ctx.fillStyle='rgba(255,255,255,0.55)'; ctx.fill();
  ctx.beginPath(); ctx.ellipse(0,R*0.17,R*0.11,R*0.032,0,0,Math.PI*2);
  ctx.fillStyle='rgba(255,255,255,0.32)'; ctx.fill();
  ctx.restore();

  var s2x = cx + R*0.44, s2y = cy + R*0.44;
  var g2 = ctx.createRadialGradient(s2x,s2y,0,s2x,s2y,Math.max(R*0.30,10));
  g2.addColorStop(0,'rgba(200,230,255,0.26)');
  g2.addColorStop(1,'rgba(200,230,255,0)');
  ctx.fillStyle=g2;
