    if(Math.sqrt(vX[qb]*vX[qb]+vZ[qb]*vZ[qb])>1.03) continue;
    if(Math.sqrt(vX[qc]*vX[qc]+vZ[qc]*vZ[qc])>1.03) continue;
    if(Math.sqrt(vX[qd]*vX[qd]+vZ[qd]*vZ[qd])>1.03) continue;

    var ux=vX[qb]-vX[qa], uy=vY[qb]-vY[qa], uz=vZ[qb]-vZ[qa];
    var wx=vX[qd]-vX[qa], wy=vY[qd]-vY[qa], wz=vZ[qd]-vZ[qa];
    var nx=uy*wz-uz*wy, ny=uz*wx-ux*wz, nz=ux*wy-uy*wx;
    var nl=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=nl; ny/=nl; nz/=nl;
    if(ny<0){ nx=-nx; ny=-ny; nz=-nz; }
    var mx=(vX[qa]+vX[qb]+vX[qc]+vX[qd])*0.25;
    var my=(vY[qa]+vY[qb]+vY[qc]+vY[qd])*0.25;
    var mz=(vZ[qa]+vZ[qb]+vZ[qc]+vZ[qd])*0.25;
