/* ---------------- render pool ---------------- */
var pool = [], poolN = 0;
var depthArr = new Float64Array(8192);
var order = [];

function pushItem(d){
  var idx = poolN;
  if(idx === pool.length) pool.push({k:0,q:null,d:0,ax:0,ay:0,bx:0,by:0,cx3:0,cy3:0,col:'',x:0,y:0,s:0,rest:false});
  poolN++;
  depthArr[idx] = d;
  return pool[idx];
}

/* ---------------- scene ---------------- */
function drawScene(){
  var cp=Math.cos(pitch), sp=Math.sin(pitch), syw=Math.sin(yaw), cyw=Math.cos(yaw);
  var ex=DIST*cp*syw, ey=DIST*sp, ez=DIST*cp*cyw;
  var fx=-ex/DIST, fy=-ey/DIST, fz=-ez/DIST;
  var rx=-fz, ry=0, rz=fx;
  var rl=Math.sqrt(rx*rx+rz*rz)||1; rx/=rl; rz/=rl;
  var ux=ry*fz-rz*fy, uy=rz*fx-rx*fz, uz=rx*fy-ry*fx;

  var i, zc, vx, vy, vz;

  for(i=0;i<VN;i++){
    vx=vX[i]-ex; vy=vY[i]-ey; vz=vZ[i]-ez;
    zc=vx*fx+vy*fy+vz*fz;
    sZ[i]=zc;
    var inv = P/(zc>0.1?zc:0.1);
    sX[i]=cx+(vx*rx+vy*ry+vz*rz)*inv;
    sY[i]=cy-(vx*ux+vy*uy+vz*uz)*inv;
  }

  poolN = 0;

  var q, it, dd;
  for(i=0;i<quads.length;i++){
    q=quads[i];
    if(q.nx*(ex-q.mx) + q.ny*(ey-q.my) + q.nz*(ez-q.mz) <= 0) continue;
    dd=(sZ[q.a]+sZ[q.b]+sZ[q.c]+sZ[q.d])*0.25;
    it = pushItem(dd);
    it.k=0; it.q=q; it.d=dd;
  }

  for(i=0;i<treeFaces.length;i++){
    var o=treeFaces[i];
    if(o.nx*(ex-o.mx) + o.ny*(ey-o.my) + o.nz*(ez-o.mz) <= 0) continue;
    var a0x=o.ax-ex, a0y=o.ay-ey, a0z=o.az-ez;
    var b0x=o.bx-ex, b0y=o.by-ey, b0z=o.bz-ez;
    var c0x=o.qx-ex, c0y=o.qy-ey, c0z=o.qz-ez;
    var za=a0x*fx+a0y*fy+a0z*fz;
    var zb=b0x*fx+b0y*fy+b0z*fz;
    var zcc=c0x*fx+c0y*fy+c0z*fz;
    if(za<0.15||zb<0.15||zcc<0.15) continue;
    var ia=P/za, ib=P/zb, ic=P/zcc;
    it = pushItem((za+zb+zcc)/3);
    it.k=1;
    it.ax=cx+(a0x*rx+a0y*ry+a0z*rz)*ia; it.ay=cy-(a0x*ux+a0y*uy+a0z*uz)*ia;
    it.bx=cx+(b0x*rx+b0y*ry+b0z*rz)*ib; it.by=cy-(b0x*ux+b0y*uy+b0z*uz)*ib;
    it.cx3=cx+(c0x*rx+c0y*ry+c0z*rz)*ic; it.cy3=cy-(c0x*ux+c0y*uy+c0z*uz)*ic;
    it.col=o.col; it.d=(za+zb+zcc)/3;
  }

  for(i=0;i<NP;i++){
    vx=pxr[i]-ex; vy=pyr[i]-ey; vz=pzr[i]-ez;
    zc=vx*fx+vy*fy+vz*fz;
    if(zc<0.3) continue;
    var inv2=P/zc;
    it = pushItem(zc);
    it.k=2;
    it.x=cx+(vx*rx+vy*ry+vz*rz)*inv2;
    it.y=cy-(vx*ux+vy*uy+vz*uz)*inv2;
    it.s=clamp(0.017*P/zc, 1.3, 7.5)*2;
    it.rest = prt[i]>0;
    it.d=zc;
  }

  var n = poolN;
  order.length = n;
  for(i=0;i<n;i++) order[i]=i;
  order.sort(function(a,b){ return depthArr[b]-depthArr[a]; });

  for(i=0;i<n;i++){
    it = pool[order[i]];
    if(it.k===0){
      q=it.q;
      ctx.globalAlpha=1;
      ctx.beginPath();
      ctx.moveTo(sX[q.a],sY[q.a]);
      ctx.lineTo(sX[q.b],sY[q.b]);
      ctx.lineTo(sX[q.c],sY[q.c]);
      ctx.lineTo(sX[q.d],sY[q.d]);
      ctx.closePath();
      ctx.fillStyle=q.col; ctx.fill();
      ctx.strokeStyle=q.col; ctx.lineWidth=1; ctx.stroke();
    } else if(it.k===1){
      ctx.globalAlpha=1;
      ctx.beginPath();
      ctx.moveTo(it.ax,it.ay); ctx.lineTo(it.bx,it.by); ctx.lineTo(it.cx3,it.cy3);
      ctx.closePath();
      ctx.fillStyle=it.col; ctx.fill();
      ctx.strokeStyle=it.col; ctx.lineWidth=0.8; ctx.stroke();
    } else {
      ctx.globalAlpha = it.rest ? 0.55 : 0.88;
      ctx.drawImage(sprite, it.x-it.s*0.5, it.y-it.s*0.5, it.s, it.s);
    }
  }
  ctx.globalAlpha=1;
}

