var last=0, tsec=0;

function frame(now){
  var dt = (now-last)/1000;
  if(!isFinite(dt) || dt<=0) dt=0.016;
  if(dt>0.05) dt=0.05;
  last=now; tsec+=dt;

  var idle = (now - lastInteract) > 4000;
  if(!dragging && pointerCount===0){
    yaw += vYaw; pitch += vPitch;
    vYaw *= 0.93; vPitch *= 0.93;
    pitch = clamp(pitch, -0.28, 1.16);
    if(idle){ yaw += 0.10*dt; vYaw=0; vPitch=0; }
  }
  shakeAmp *= Math.exp(-5.5*dt);

  updateSnow(dt, tsec);
  computeProjection();

  var jx = (Math.random()-0.5)*R*shakeAmp;
  var jy = (Math.random()-0.5)*R*shakeAmp;

  ctx.setTransform(DPR,0,0,DPR,0,0);
  drawBackground();

  ctx.setTransform(DPR,0,0,DPR,jx*DPR,jy*DPR);
  drawStandBack();

  ctx.save();
  ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.clip();
  drawScene();
  ctx.restore();

  drawGlass();
  drawCollarFront();

  requestAnimationFrame(frame);
}

