});

canvas.addEventListener('pointermove', function(e){
  if(!pts[e.pointerId]) return;
  var prev=pts[e.pointerId];
  var dx=e.clientX-prev.x, dy=e.clientY-prev.y;
  prev.x=e.clientX; prev.y=e.clientY;

  if(pointerCount>=2){
    var arr=[], kk;
    for(kk in pts) arr.push(pts[kk]);
    if(arr.length>=2){
      var pd=Math.sqrt(Math.pow(arr[0].x-arr[1].x,2)+Math.pow(arr[0].y-arr[1].y,2));
      if(pinchPrev>0 && pd>0){ zoom = clamp(zoom*(pd/pinchPrev), 0.85, 1.20); }
      pinchPrev=pd;
    }
  } else if(dragging){
    yaw -= dx*0.0062;
    pitch = clamp(pitch + dy*0.0050, -0.28, 1.16);
    vYaw = -dx*0.0062*0.55;
    vPitch = dy*0.0050*0.55;
    moved += Math.abs(dx)+Math.abs(dy);
  }
  lastInteract=performance.now();
});

function endPointer(e){
  if(!pts[e.pointerId]) return;
  delete pts[e.pointerId];
  pointerCount=0; for(var k in pts) pointerCount++;
  pinchPrev=0;
  if(pointerCount===0){
    canvas.classList.remove('grabbing');
    if(dragging && moved<7 && (performance.now()-downT)<340){ shake(1); }
    dragging=false;
  }
  lastInteract=performance.now();
}
canvas.addEventListener('pointerup', endPointer);
canvas.addEventListener('pointercancel', endPointer);

canvas.addEventListener('wheel', function(e){
  e.preventDefault();
  zoom = clamp(zoom*Math.exp(-e.deltaY*0.0012), 0.85, 1.20);
  lastInteract=performance.now();
}, {passive:false});

canvas.addEventListener('dblclick', function(){
  yaw=0.75; pitch=0.26; vYaw=0; vPitch=0; zoom=1;
  lastInteract=performance.now();
});

window.addEventListener('keydown', function(e){
  if(e.code==='Space'){ e.preventDefault(); shake(1); }
  else if(e.key==='r'||e.key==='R'){ yaw=0.75; pitch=0.26; vYaw=0; vPitch=0; zoom=1; }
