/* ---------------- render pool ---------------- */
var pool = [], poolN = 0;
var depthArr = new Float64Array(8192);
var order = [];

function pushItem(d){
  var idx = poolN;
  if(idx === pool.length) pool.push({k:0,q:null,d:0,ax:0,ay:0,bx:0,by:0,cx3:0,cy3:0,col:'',x:0,y:0,s:0,rest:false});
  poolN++;
