/* ---------------- scene ---------------- */
function drawScene(){
  var cp=Math.cos(pitch), sp=Math.sin(pitch), syw=Math.sin(yaw), cyw=Math.cos(yaw);
  var ex=DIST*cp*syw, ey=DIST*sp, ez=DIST*cp*cyw;
  var fx=-ex/DIST, fy=-ey/DIST, fz=-ez/DIST;
  var rx=-fz, ry=0, rz=fx;
  var rl=Math.sqrt(rx*rx+rz*rz)||1; rx/=rl; rz/=rl;
  var ux=ry*fz-rz*fy, uy=rz*fx-rx*fz, uz=rx*fy-ry*fx;

  var i, zc, vx, vy, vz;

  for(i=0;i<VN;i++){
    vx=vX[i]-ex; vy=vY[i]-ey; vz=vZ[i]-ez;
    zc=vx*fx+vy*fy+vz*fz;
    sZ[i]=zc;
    var inv = P/(zc>0.1?zc:0.1);
    sX[i]=cx+(vx*rx+vy*ry+vz*rz)*inv;
    sY[i]=cy-(vx*ux+vy*uy+vz*uz)*inv;
  }

  poolN = 0;

  var q, it;
  for(i=0;i<quads.length;i++){
    q=quads[i];
    if(q.nx*(ex-q.mx) + q.ny*(ey-q.my) + q.nz*(ez-q.mz) <= 0) continue;
    var dd=(sZ[q.a]+sZ[q.b]+sZ[q.c]+sZ[q.d])*0.25;
    it = pushItem(dd);
    it.k=0; it.q=q; it.d=dd;
  }

  for(i=0;i<treeFaces.length;i++){
    var o=treeFaces[i];
    if(o.nx*(ex-o.mx) + o.ny*(ey-o.my) + o.nz*(ez-o.mz) <= 0) continue;
    var a0x=o.ax-ex, a0y=o.ay-ey, a0z=o.az-ez;
    var b0x=o.bx-ex, b0y=o.by-ey, b0z=o.bz-ez;
    var c0x=o.qx-ex, c0y=o.qy-ey, c0z=o.qz-ez;
    var za=a0x*fx+a0y*fy+a0z*fz;
    var zb=b0x*fx+b0y*fy+b0z*fz;
    var zcc=c0x*fx+c0y*fy+c0z*fz;
    if(za<0.15||zb<0.15||zcc<0.15) continue;
    var ia=P/za, ib=P/zb, ic=P/zcc;
    it = pushItem((za+zb+zcc)/3);
    it.k=1;
    it.ax=cx+(a0x*rx+a0y*ry+a0z*rz)*ia; it.ay=cy-(a0x*ux+a0y*uy+a0z*uz)*ia;
    it.bx=cx+(b0x*rx+b0y*ry+b0z*rz)*ib; it.by=cy-(b0x*ux+b0y*uy+b0z*uz)*ib;
    it.cx3=cx+(c0x*rx+c0y*ry+c0z*rz)*ic; it.cy3=cy-(c0x*ux+c0y*uy+c0z*uz)*ic;
    it.col=o.col; it.d=(za+zb+zcc)/3;
