  order.length = n;
  for(i=0;i<n;i++) order[i]=i;
  order.sort(function(a,b){ return depthArr[b]-depthArr[a]; });

  for(i=0;i<n;i++){
    it = pool[order[i]];
    if(it.k===0){
      q=it.q;
      ctx.globalAlpha=1;
      ctx.beginPath();
      ctx.moveTo(sX[q.a],sY[q.a]);
      ctx.lineTo(sX[q.b],sY[q.b]);
      ctx.lineTo(sX[q.c],sY[q.c]);
      ctx.lineTo(sX[q.d],sY[q.d]);
      ctx.closePath();
      ctx.fillStyle=q.col; ctx.fill();
      ctx.strokeStyle=q.col; ctx.lineWidth=1; ctx.stroke();
    } else if(it.k===1){
      ctx.globalAlpha=1;
      ctx.beginPath();
      ctx.moveTo(it.ax,it.ay); ctx.lineTo(it.bx,it.by); ctx.lineTo(it.cx3,it.cy3);
      ctx.closePath();
      ctx.fillStyle=it.col; ctx.fill();
      ctx.strokeStyle=it.col; ctx.lineWidth=0.8; ctx.stroke();
    } else {
      ctx.globalAlpha = it.rest ? 0.55 : 0.88;
      ctx.drawImage(sprite, it.x-it.s*0.5, it.y-it.s*0.5, it.s, it.s);
    }
  }
  ctx.globalAlpha=1;
}

/* ---------------- main loop ---------------- */
var last=0, tsec=0;

function frame(now){
  var dt = (now-last)/1000;
  if(!isFinite(dt) || dt<=0) dt=0.016;
  if(dt>0.05) dt=0.05;
  last=now; tsec+=dt;

  var idle = (now - lastInteract) > 4000;
  if(!dragging && pointerCount===0){
