  }
  shakeAmp *= Math.exp(-5.5*dt);

  updateSnow(dt, tsec);
  computeProjection();

  var jx = (Math.random()-0.5)*R*shakeAmp;
  var jy = (Math.random()-0.5)*R*shakeAmp;

  ctx.setTransform(DPR,0,0,DPR,0,0);
  drawBackground();

  ctx.setTransform(DPR,0,0,DPR,jx*DPR,jy*DPR);
