  ctx.save();
  ctx.beginPath(); ctx.arc(cx,cy,R,0,Math.PI*2); ctx.clip();
  drawScene();
  ctx.restore();

  drawGlass();
  drawStandFront();

  requestAnimationFrame(frame);
}

