}

/* ---------------- terrain mesh ---------------- */
var N = 30;
var G0 = -1.06, GD = (1.06 - (-1.06))/N;
var VN = (N+1)*(N+1);
var vX = new Float64Array(VN), vY = new Float64Array(VN), vZ = new Float64Array(VN), vH = new Float64Array(VN);
var sX = new Float64Array(VN), sY = new Float64Array(VN), sZ = new Float64Array(VN);

for(var vj=0; vj<=N; vj++){
  for(var vi=0; vi<=N; vi++){
    var gx = G0 + vi*GD, gz = G0 + vj*GD;
    var vidx = vj*(N+1)+vi;
    var gh = heightAt(gx,gz);
    vX[vidx]=gx; vZ[vidx]=gz; vH[vidx]=gh; vY[vidx]=BASE_Y + gh*H_SCALE;
  }
}

var quads = [];
for(var qj=0; qj<N; qj++){
  for(var qi=0; qi<N; qi++){
    var qa = qj*(N+1)+qi, qb=qa+1, qc=qa+N+2, qd=qa+N+1;
    if(Math.sqrt(vX[qa]*vX[qa]+vZ[qa]*vZ[qa])>1.03) continue;
    if(Math.sqrt(vX[qb]*vX[qb]+vZ[qb]*vZ[qb])>1.03) continue;
    if(Math.sqrt(vX[qc]*vX[qc]+vZ[qc]*vZ[qc])>1.03) continue;
    if(Math.sqrt(vX[qd]*vX[qd]+vZ[qd]*vZ[qd])>1.03) continue;

    var ux=vX[qb]-vX[qa], uy=vY[qb]-vY[qa], uz=vZ[qb]-vZ[qa];
    var wx=vX[qd]-vX[qa], wy=vY[qd]-vY[qa], wz=vZ[qd]-vZ[qa];
    var nx=uy*wz-uz*wy, ny=uz*wx-ux*wz, nz=ux*wy-uy*wx;
    var nl=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=nl; ny/=nl; nz/=nl;
    if(ny<0){ nx=-nx; ny=-ny; nz=-nz; }
    var mx=(vX[qa]+vX[qb]+vX[qc]+vX[qd])*0.25;
    var my=(vY[qa]+vY[qb]+vY[qc]+vY[qd])*0.25;
    var mz=(vZ[qa]+vZ[qb]+vZ[qc]+vZ[qd])*0.25;
    var hAvg=(vH[qa]+vH[qb]+vH[qc]+vH[qd])*0.25;
    quads.push({
      a:qa, b:qb, c:qc, d:qd, nx:nx, ny:ny, nz:nz, mx:mx, my:my, mz:mz,
      col: terrainColor(hAvg,nx,ny,nz,(qi*7+qj*13)%9)
    });
  }
}

/* ---------------- trees ---------------- */
function mulberry32(a){
  return function(){
    a |= 0; a = a + 0x6D2B79F5 | 0;
    var t = Math.imul(a ^ a>>>15, 1|a);
    t = t + Math.imul(t ^ t>>>7, 61|t) ^ t;
    return ((t ^ t>>>14)>>>0)/4294967296;
  };
}

var treeFaces = [];
function addTri(ax,ay,az, bx,by,bz, qx,qy,qz, col, refX,refY,refZ){
  var ux=bx-ax, uy=by-ay, uz=bz-az;
  var wx=qx-ax, wy=qy-ay, wz=qz-az;
  var nx=uy*wz-uz*wy, ny=uz*wx-ux*wz, nz=ux*wy-uy*wx;
  var nl=Math.sqrt(nx*nx+ny*ny+nz*nz)||1; nx/=nl; ny/=nl; nz/=nl;
  var mx=(ax+bx+qx)/3, my=(ay+by+qy)/3, mz=(az+bz+qz)/3;
  if(refX!==undefined){
    var ox=mx-refX, oy=my-refY, oz=mz-refZ;
    if(nx*ox+ny*oy+nz*oz<0){ nx=-nx; ny=-ny; nz=-nz; }
  }
  treeFaces.push({
    ax:ax,ay:ay,az:az, bx:bx,by:by,bz:bz, qx:qx,qy:qy,qz:qz,
    nx:nx,ny:ny,nz:nz, mx:mx,my:my,mz:mz,
    col: shade(col[0],col[1],col[2],nx,ny,nz)
