#shakeBtn{position:fixed;left:50%;bottom:3.4vh;transform:translateX(-50%);z-index:3;padding:11px 32px;border-radius:999px;border:1px solid rgba(150,190,255,.35);background:linear-gradient(180deg,rgba(120,165,255,.20),rgba(60,100,190,.14));color:#dce9ff;font-size:12px;font-weight:600;letter-spacing:.20em;text-transform:uppercase;cursor:pointer;font-family:inherit;transition:transform .18s,box-shadow .25s,background .25s}
